/**
 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
 */
import { eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUser } from "./_mappers";
import type { UpdateProfileInput } from "@/schemas/member";
import type { UserId } from "@/types/common";
import type { User } from "@/types/member";

export async function findUserById(userId: UserId): Promise<User | null> {
  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

/**
 * Addresses are matched as stored. The auth schemas lowercase what the forms
 * submit, so a lookup already arrives in the stored spelling.
 */
export async function findUserByEmail(email: string): Promise<User | null> {
  const rows = getDb()
    .select()
    .from(users)
    .where(eq(users.email, email))
    .all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function insertUser(input: {
  email: string;
  name: string;
  passwordHash: string;
}): Promise<User> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(users)
    .values({
      id: newId(),
      // Stored as typed: the welcome email is addressed with this value.
      email: input.email,
      name: input.name,
      passwordHash: input.passwordHash,
      avatarUrl: null,
      timezone: "UTC",
      emailVerifiedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toUser(row);
}

export async function updateUser(
  userId: UserId,
  patch: UpdateProfileInput,
): Promise<User> {
  const row = getDb()
    .update(users)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(users.id, userId))
    .returning()
    .get();

  if (!row) throw new Error(`User ${userId} not found`);
  return toUser(row);
}

/**
 * The password hash never travels on the `User` domain type — nothing outside
 * `AuthService` may see it — so login reads it through this narrow accessor.
 *
 * Not in the manifest: added because `User` deliberately omits the column and
 * credential login has no other way to reach it.
 */
export async function findPasswordHash(
  userId: UserId,
): Promise<string | null> {
  const row = getDb()
    .select({ passwordHash: users.passwordHash })
    .from(users)
    .where(eq(users.id, userId))
    .get();
  return row?.passwordHash ?? null;
}

/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
export async function updatePasswordHash(
  userId: UserId,
  passwordHash: string,
): Promise<void> {
  getDb()
    .update(users)
    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(users.id, userId))
    .run();
}

/** Batch fetch used by every list view that decorates rows with their author. */
export async function findUsersByIds(
  userIds: readonly UserId[],
): Promise<readonly User[]> {
  if (userIds.length === 0) return [];
  const rows = getDb()
    .select()
    .from(users)
    .where(inArray(users.id, [...userIds]))
    .all();
  return rows.map(toUser);
}
import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, timestampColumns } from "./_shared";

/** Users are global, not tenant-scoped: one account can join many orgs. */
export const users = sqliteTable(
  "users",
  {
    id: idColumn(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    avatarUrl: text("avatar_url"),
    timezone: text("timezone").notNull().default("UTC"),
    emailVerifiedAt: text("email_verified_at"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("users_email_idx").on(table.email)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    id: idColumn(),
    userId: text("user_id").notNull(),
    activeOrgId: text("active_org_id"),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("sessions_token_idx").on(table.tokenHash)],
);

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: idColumn(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  ...timestampColumns,
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
export type SessionRow = typeof sessions.$inferSelect;
/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
  WebhookId,
} from "@/types/common";

/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
