/**
 * Email-address rules shared by every entry point that creates or looks up an
 * account. Addresses are case-insensitive (ADR 0003): they are stored and
 * compared in this one canonical spelling, whichever way they were typed.
 */

export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/** Sign-up was refused because the address already has an account. */
export class EmailTakenError extends Error {
  readonly code = "conflict" as const;

  constructor(message = "An account with that email already exists") {
    super(message);
    this.name = "EmailTakenError";
  }
}

