const { getDb, users, organizations } = await import("@/server/db");
const pw = "Correct1Horse2";
let i = 0;
async function reg(name: string, email?: string) {
  i++;
  resetRateLimits();
  try {
    const r = await register({ name, email: email ?? `u${i}@x.com`, password: pw, confirmPassword: pw, acceptTerms: true } as any);
    console.log(JSON.stringify(name).slice(0, 50), "->", JSON.stringify(r.org.name), r.org.name.length, "|", r.org.slug, "|", r.user.email);
